338	                new TaskActionRequest(createKey)), HttpStatus.CONFLICT);
339	        // 完成：同键重放首次结果（终态同类重复操作按幂等规则返回）
340	        String completeKey = key();
341	        TaskView done = service.completeTask("INC-I1", "T-1", "alice",
