                "SELECT * FROM incident_zones WHERE zone_key = ?", ZONE_MAPPER, zoneKey);
        return rows.stream().findFirst();
    }

    /**
     * 查询事件全部区域版本，按登记顺序返回。
     */
    public List<EvacuationZone> listZonesByIncident(long incidentId) {
