                Timestamp.from(at), zoneId);
    }

    // ---------- 撤离豁免 ----------

    /**
     * 签发豁免，返回生成主键。(incident_id, task_key, zone_id, zone_version) 唯一。
     *
     * @throws DuplicateKeyException 同一任务对同一区域版本已持有豁免时抛出
     */
    public long insertExemption(ZoneExemption exemption) {
