    }

    // ---------- 疏散区域 ----------

    /**
     * 插入区域（新版本），返回生成主键。zone_key 唯一约束兜底并发重复登记。
     */
    public long insertZone(EvacuationZone zone) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement(
