public void refresh(Incident incident) {
    Instant now = now();
    List<EvacuationZone> all = evacuation.listZonesByIncident(incident.id());
    for (zone : all) {
        boolean current = zone.supersededAt() == null;
        if (current && zone.effectiveAt(now)) {
            activateBlocks(incident, zone, now);
        } else if (!current || zone.endedAt(now)) {
            evacuation.releaseBlocksByZone(zone.id(), now);
        }
    }
    // restore tasks no longer blocked
    for (task : tasks.listEvacuationBlockedByIncident(incident.id())) {
        if (!evacuation.hasAnyActiveBlock(task.id())) tasks.restoreOpen(task.id(), now);
    }
}

private void activateBlocks(Incident incident, EvacuationZone zone, Instant now) {
    for (task : tasks.listOpenByIncident(incident.id())) {
        if (!Grids.intersects(task.workGrids(), zone.grids())) continue;
        if (evacuation.hasActiveBlock(task.id(), zone.id())) continue;
        if (hasValidExemption(incident.id(), task.taskKey(), zone)) continue;
        evacuation.insertBlock(snapshot...);
        tasks.markEvacuationBlocked(task.id(), now);
    }
}

boolean hasValidExemption(long incidentId, String taskKey, EvacuationZone zone) {
    return evacuation.findExemption(incidentId, taskKey, zone.id(), zone.version()).isPresent();
}
