        // 不同 commandKey、同内容同操作者：zoneKey 指纹相同，重放首次结果，不产生新区域
        ZoneView replay = zones.registerZone("INC-ZR", "alice",
                new ZoneRegisterRequest(key(), req.grids(), req.effectiveFrom(),
                        req.effectiveTo(), req.riskLevel()));
